<h3>Active entitlements</h3><?php foreach($subscriptionEntitlements as $entitlement): ?><article class="form-card"><strong><?php echo e((string)$entitlement['yuva_id']); ?></strong> · <?php echo e((string)$entitlement['display_name']); ?> · <?php echo e((string)$entitlement['source_type']); ?><form action="admin-subscription-action.php" method="post"><?php echo csrf_field(); ?><input type="hidden" name="action" value="revoke"><input type="hidden" name="entitlement_guid" value="<?php echo e((string)$entitlement['entitlement_guid']); ?>"><label><input type="checkbox" name="block_future" value="1"> Also block future beta redemption</label><button class="button ghost">Revoke</button></form></article><?php endforeach; ?><h3>Audit history</h3><div class="table-wrap"><table><thead><tr><th>Time</th><th>Action</th><th>Actor role</th><th>Entity</th><th>Result</th></tr></thead><tbody><?php foreach($subscriptionAudit as $event): ?><tr><td><?php echo e((string)$event['created_at']); ?></td><td><?php echo e((string)$event['action_type']); ?></td><td><?php echo e((string)$event['actor_role']); ?></td><td><?php echo e((string)$event['entity_type'].' '.(string)$event['entity_reference']); ?></td><td><?php echo !empty($event['succeeded'])?'PASS':'REJECTED'; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
